package main

import (
	"errors"
	"fmt"
)

// 1) 参数立即求值 vs 闭包延迟求值
func loopDefer() {
	for i := 0; i < 3; i++ {
		defer fmt.Println("arg:", i)              // 注册时拷贝 i：输出 2,1,0
		defer func() { fmt.Println("clo:", i) }() // 闭包捕获引用：循环结束 i=3，输出三个 3
	}
}

// 2) 命名返回值 + defer 包装错误
func readConfig() (cfg string, err error) {
	defer func() {
		if err != nil {
			err = fmt.Errorf("readConfig: %w", err) // 命名返回值才能在 defer 里改
		}
	}()
	return "", errors.New("file not found")
}

// 3) recover 包一层就失效
func badRecover() {
	defer logRecover() // helper 里 recover() 永远返回 nil
	panic("won't be caught")
}
func logRecover() {
	if r := recover(); r != nil {
		fmt.Println("caught:", r)
	}
}

// 4) 正确写法：recover 必须直接在 deferred 函数体
func safeRun(fn func()) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("panic: %v", r) // 直接调用 recover，sp 匹配才生效
		}
	}()
	fn()
	return nil
}

// 5) 跨 goroutine panic 必须各自 defer recover
func spawn() {
	go func() {
		defer func() { _ = recover() }() // 没这一行，子 goroutine panic 直接 crash 整个进程
		panic("in child")
	}()
}
